// stlport
//
// FireSpreadUpdate::calcNextSpreadDelay (0x0048B7D9, 36 bytes) and
// FireSpreadUpdate::startFireSpreading (0x0048B938, 39 bytes), from the Zero
// Hour FireSpreadUpdate.cpp, compiled against the TU's FireSpreadUpdateView.h.
// Target facts: GetGameLogicRandomValue 0x00233FF4 gets the module data's
// min/max (+0xC/+0x10) with the retail file literal and line 152; the result is
// clamped to at least 1. BFME 2's AFLAME status is bit 10 (ZH's enum has 11),
// tested through the rowed Object::testStatus.
#define BFME_SNAPSHOT_NAME_SLOT
#include "PreRTS.h"	// This must go first in EVERY cpp file int the GameEngine
#include "GameLogic/Module/UpdateModule.h"
#include "GameLogic/Object.h"
#include "FireSpreadUpdateView.h"

Int GetGameLogicRandomValue( int lo, int hi, char *file, int line );

static const ObjectStatusTypes BFME_OBJECT_STATUS_AFLAME = (ObjectStatusTypes)10;

//-------------------------------------------------------------------------------------------------
//-------------------------------------------------------------------------------------------------
UnsignedInt FireSpreadUpdate::calcNextSpreadDelay()
{
	const FireSpreadUpdateModuleData* d = getFireSpreadUpdateModuleData();
	UnsignedInt delay = GetGameLogicRandomValue( d->m_minSpreadTryDelayData, d->m_maxSpreadTryDelayData,
		"C:\\projects\\bfme2patch103\\bfme2\\Code\\GameEngine\\Source\\GameLogic\\Object\\Update\\FireSpreadUpdate.cpp", 152 );
	if (delay < 1)
		delay = 1;
	return delay;
}

//-------------------------------------------------------------------------------------------------
//-------------------------------------------------------------------------------------------------
void FireSpreadUpdate::startFireSpreading()
{
	Object *obj = getObject();
	if( !obj->testStatus( BFME_OBJECT_STATUS_AFLAME ) )
		return;	// sorry, must be on fire

	setWakeFrame(obj, UPDATE_SLEEP(calcNextSpreadDelay()));
}
